import json
from pathlib import Path
A=[]
def add(i,s,q,m,c='material',stage='recognized',**kw):A.append(dict(index=i,classification=c,summary=s,rows=[dict(quote=q,model_quantity=m,stage=stage,issuer_treatment=s,**kw)]))
add(192,'Exercice 2025 : charge equity de 55,75 M$ hors DSU administrateurs, 56,605 M$ en périmètre élargi. Les unités Non-Treasury prévoient un règlement cash et passif résiduel de 1 M$ ; les SAR sont convertis du cash vers actions en août. Valeur intrinsèque des options exercées de 201,6 M$ n’est pas le cash reçu par Galaxy. Devises CAD/USD changent à la réorganisation, à conserver pour comparer.','grants are settled solely in cash','cash_settled_employee_awards_distinct_from_equity_awards',c='context',measurement_basis='NonTreasury_cash_settlement;not_all_SBC_non_cash;CAD_USD_post_reorganization')
add(193,'Fin 2025 : TRA de 150,4 M$ dont 72,3 M$ envers parties liées, paiements futurs dépendant d’événements et économies fiscales. Distributions fiscales de 49,3 M$ réellement payées, pas un investissement IA. Billet GDHI/GDH LP éliminé à la consolidation après réorganisation, sans preuve de remboursement cash. Candy cesse d’être partie liée après acquisition et départ du dirigeant ; sponsoring des fonds ne suffit pas au contrôle.','The Promissory Note is eliminated in consolidation subsequent to the Reorganization Transactions.','related_party_note_consolidation_elimination_not_cash_repayment',c='context',counterparty_evidence='anonymous')
add(194,'La politique confirme ventes de crypto généralement brutes, stablecoins financiers en net, échanges crypto/crypto non cash et actifs clients/collatéraux assortis d’obligations de restitution. Certains emprunts crypto sont rappelables à vue ; NAV de fonds fermés ne constitue pas cash immédiatement disponible. GDI consolide GDH LP comme seul GP malgré minoritaires économiques. Infrastructure datacenter amortie sur 15–25 ans ; D&A classé en frais généraux et plafonds de taux en OCI ne réduisent pas le principal de dette.','The Company predominantly acts as a principal in sales and purchases of digital intangible assets','crypto_gross_revenue_non_cash_exchanges_not_hpc_cash_generation',c='context',measurement_basis='FY2025_USGAAP_consolidation_GDHLP;crypto_gross_vs_net;restricted_collateral')
add(195,'Fin 2025 : dettes construction/minage 84,901 M$ non ventilées, distinctes des engagements de construction Helios de 529,8 M$ ; ne pas attribuer le total mixte à Helios seul. Dépôts d’achat 34,168 M$ et prépayés 43,721 M$ ne sont pas du cash libre. Disparition du billet de 96,933 M$ résulte de l’élimination en consolidation, pas d’un remboursement démontré.','the Promissory Note between GDH LP and GDI was eliminated in consolidation','intercompany_note_eliminated_not_cash_repaid',c='context',measurement_basis='Dec2025_mixed_construction_mining_AP84_901m;no_Helios_allocation')
Path(__file__).with_suffix('.json').write_text(json.dumps(A,ensure_ascii=False,indent=2)+'\n')
M=json.loads(Path('work/continuation398/scope.json').read_text())['rows']
for a in A:
 t=json.loads(Path(M[a['index']]['path']).read_text())['text']
 for r in a['rows']:assert r['quote'] in t,(a['index'],r['quote'])
